import anthropic, json
client = anthropic.Anthropic()

# Step 1: Define tools
tools = [
    {
        "name": "get_weather",
        "description": "Get the current weather for a city. Use when the user asks about weather.",
        "input_schema": {
            "type": "object",
            "properties": {
                "city": {"type": "string", "description": "City name, e.g. 'Paris'"},
                "units": {"type": "string", "enum": ["celsius", "fahrenheit"], "default": "celsius"}
            },
            "required": ["city"]
        }
    }
]

# Step 2: First call — model may request a tool
response = client.messages.create(
    model="claude-haiku-5-5",
    max_tokens=1024,
    tools=tools,
    messages=[{"role": "user", "content": "What's the weather in Paris right now?"}]
)

print(f"Stop reason: {response.stop_reason}")  # tool_use

if response.stop_reason == "tool_use":
    tool_call = next(b for b in response.content if b.type == "tool_use")
    print(f"Model wants to call: {tool_call.name}")
    print(f"With input: {tool_call.input}")
    # {"city": "Paris", "units": "celsius"}
